fn check() {
    let mut s=A; let mut k=[0u64;64]; unsafe{p_s_a(s.as_mut_ptr(),k.as_mut_ptr(),RC.as_ptr())} assert_eq!(s,W);
    let mut s=A; let mut k=[0u64;64]; unsafe{p_s_b(s.as_mut_ptr(),k.as_mut_ptr(),RC.as_ptr())} assert_eq!(s,W);
    let mut s=A; let mut k=[0u64;64]; unsafe{p_s_c(s.as_mut_ptr(),k.as_mut_ptr(),RC.as_ptr())} assert_eq!(s,W);
    let mut s=A; let mut k=[0u64;64]; unsafe{p_s_d(s.as_mut_ptr(),k.as_mut_ptr(),RC.as_ptr())} assert_eq!(s,W);
    let mut s=A; let mut k=[0u64;64]; unsafe{p_s_e(s.as_mut_ptr(),k.as_mut_ptr(),RC.as_ptr())} assert_eq!(s,W);
    let mut s=A; let mut k=[0u64;64]; unsafe{p_s_f(s.as_mut_ptr(),k.as_mut_ptr(),RC.as_ptr())} assert_eq!(s,W);
}
pub fn bench(c: &mut Criterion) {
    check();
    let mut g = c.benchmark_group("proto");
    let mut s = [1u64; 50];
    let mut k = [0u64; 64];
    g.bench(BenchmarkId::new(VG, 400), |b| b.iter(|| unsafe { p_s_a(s.as_mut_ptr(), k.as_mut_ptr(), RC.as_ptr()) }));
    g.bench(BenchmarkId::new(VG, 401), |b| b.iter(|| unsafe { p_s_b(s.as_mut_ptr(), k.as_mut_ptr(), RC.as_ptr()) }));
    g.bench(BenchmarkId::new(VG, 402), |b| b.iter(|| unsafe { p_s_c(s.as_mut_ptr(), k.as_mut_ptr(), RC.as_ptr()) }));
    g.bench(BenchmarkId::new(VG, 403), |b| b.iter(|| unsafe { p_s_d(s.as_mut_ptr(), k.as_mut_ptr(), RC.as_ptr()) }));
    g.bench(BenchmarkId::new(VG, 404), |b| b.iter(|| unsafe { p_s_e(s.as_mut_ptr(), k.as_mut_ptr(), RC.as_ptr()) }));
    g.bench(BenchmarkId::new(VG, 405), |b| b.iter(|| unsafe { p_s_f(s.as_mut_ptr(), k.as_mut_ptr(), RC.as_ptr()) }));
    g.finish();
}
